import java.util.*;public class Task11{static class Ticket{final String reg,type;final int floor,slot;Ticket(String r,String t,int f,int s){reg=r;type=t;floor=f;slot=s;}}static class Parking{final String[][]slots;final Map<String,Ticket>active=new HashMap<>();double total;Parking(int...n){slots=new String[n.length][];for(int i=0;i<n.length;i++)slots[i]=new String[n[i]];}Ticket enter(String r,String t){if(active.containsKey(r))throw new IllegalArgumentException("Duplicate registration");if(!t.equals("Bike")&&!t.equals("Car")&&!t.equals("EV"))throw new IllegalArgumentException("Unknown type");for(int f=0;f<slots.length;f++)for(int s=0;s<slots[f].length;s++)if(slots[f][s]==null){slots[f][s]=r;Ticket z=new Ticket(r,t,f,s);active.put(r,z);return z;}throw new IllegalStateException("Full");}double exit(String r,int m,boolean pass,int k){Ticket t=active.get(r);if(t==null||m<0||k<0)throw new IllegalArgumentException("Invalid exit");double rate=t.type.equals("Bike")?10:30,fee=pass?0:((m+59)/60)*rate;if(t.type.equals("EV"))fee+=k*12;slots[t.floor][t.slot]=null;active.remove(r);total+=fee;return fee;}}public static void main(String[]x){Parking p=new Parking(2,1);p.enter("TN01","Bike");p.enter("TN02","Car");p.enter("TN03","EV");System.out.println("Full occupancy: "+p.active.size());try{p.enter("TN04","Car");}catch(Exception e){System.out.println("Last slot boundary: full");}System.out.println("Bike 0 min: Rs "+p.exit("TN01",0,false,0));System.out.println("Car 60 min: Rs "+p.exit("TN02",60,false,0));System.out.println("EV 61 min plus 5 kWh: Rs "+p.exit("TN03",61,false,5));System.out.println("Total: Rs "+p.total);try{p.enter("TN05","Truck");}catch(Exception e){System.out.println("Unknown type rejected");}}}